import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);

  const colors = {
    surface: 0x14141a,
    accent: 0xff2a38,
    paper: 0xe8ecf2
  };

  const gridWidth = 5.5;
  const gridHeight = 3.5;
  const gutterSize = 0.25;
  const cellDepth = 0.06;
  const cardPadding = 0.5;

  const dominantCellW = 3.25;
  const dominantCellH = 3.5;
  const secondaryCellW = 2.0;
  const secondaryCellH = 1.625;

  // Create gradient texture
  const gradientData = new Uint8Array(512 * 512 * 3);
  for (let y = 0; y < 512; y++) {
    for (let x = 0; x < 512; x++) {
      const idx = (y * 512 + x) * 3;
      const t = Math.min(1, (x + y) / 768);

      const r1 = 0x10, g1 = 0x10, b1 = 0x17;
      const r2 = 0x1a, g2 = 0x1a, b2 = 0x22;

      gradientData[idx] = Math.floor(r1 + (r2 - r1) * t);
      gradientData[idx + 1] = Math.floor(g1 + (g2 - g1) * t);
      gradientData[idx + 2] = Math.floor(b1 + (b2 - b1) * t);

      if (Math.abs(t - 0.4) < 0.05) {
        gradientData[idx] = Math.min(255, gradientData[idx] + 20);
        gradientData[idx + 1] = Math.min(255, gradientData[idx + 1] + 20);
        gradientData[idx + 2] = Math.min(255, gradientData[idx + 2] + 20);
      }
    }
  }

  const gradientTexture = new THREE.DataTexture(gradientData, 512, 512, THREE.RGBFormat);
  gradientTexture.needsUpdate = true;

  const cellMaterial = new THREE.MeshStandardMaterial({
    map: gradientTexture,
    metalness: 0.45,
    roughness: 0.5,
    clearcoat: 0.2,
    color: colors.surface,
    transparent: true,
    opacity: 1
  });

  function createCell(width, height, x, y) {
    const geometry = new THREE.BoxGeometry(width, height, cellDepth);
    const mesh = new THREE.Mesh(geometry, cellMaterial);
    mesh.position.set(x, y, 0);
    mesh.castShadow = true;
    mesh.receiveShadow = true;

    const tickGeometry = new THREE.BoxGeometry(0.4, 0.05, cellDepth * 1.5);
    const tickMaterial = new THREE.MeshBasicMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: 1.3,
      transparent: true,
      opacity: 1
    });
    const tickMesh = new THREE.Mesh(tickGeometry, tickMaterial);
    const tickX = -(width / 2) + cardPadding + 0.2;
    const tickY = (height / 2) - cardPadding - 0.025;
    tickMesh.position.set(tickX, tickY, cellDepth / 2 + 0.02);
    tickMesh.userData.isTickBar = true;
    mesh.add(tickMesh);

    return { mesh, tickMesh };
  }

  const cells = [];
  const allTickBars = [];
  const timelines = [];

  const dominantX = -gridWidth / 2 + dominantCellW / 2;
  const dominantY = 0;
  const { mesh: dominantMesh, tickMesh: dominantTick } = createCell(dominantCellW, dominantCellH, dominantX, dominantY);
  cells.push(dominantMesh);
  allTickBars.push(dominantTick);
  group.add(dominantMesh);

  const sec1X = dominantX + dominantCellW / 2 + gutterSize + secondaryCellW / 2;
  const sec1Y = gridHeight / 2 - secondaryCellH / 2;
  const { mesh: sec1Mesh, tickMesh: sec1Tick } = createCell(secondaryCellW, secondaryCellH, sec1X, sec1Y);
  cells.push(sec1Mesh);
  allTickBars.push(sec1Tick);
  group.add(sec1Mesh);

  const sec2X = sec1X;
  const sec2Y = -gridHeight / 2 + secondaryCellH / 2;
  const { mesh: sec2Mesh, tickMesh: sec2Tick } = createCell(secondaryCellW, secondaryCellH, sec2X, sec2Y);
  cells.push(sec2Mesh);
  allTickBars.push(sec2Tick);
  group.add(sec2Mesh);

  const headerText = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 700,
    color: colors.paper
  });
  headerText.position.set(-gridWidth / 2 + 0.25, gridHeight / 2 + 0.5, 0.1);
  group.add(headerText);

  const dominantValueText = ctx.fontAtlas.createText('0.002 mm', {
    fontFamily: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    color: colors.paper
  });
  dominantValueText.position.set(dominantX - dominantCellW / 2 + cardPadding, dominantY + 0.3, cellDepth / 2 + 0.02);
  dominantMesh.add(dominantValueText);

  const dominantLabelText = ctx.fontAtlas.createText('Case tolerance, CNC pass', {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    color: colors.paper
  });
  dominantLabelText.position.set(dominantX - dominantCellW / 2 + cardPadding, dominantY - 0.4, cellDepth / 2 + 0.02);
  dominantMesh.add(dominantLabelText);

  const sec1ValueText = ctx.fontAtlas.createText('38 h', {
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    color: colors.paper
  });
  sec1ValueText.position.set(sec1X - secondaryCellW / 2 + cardPadding, sec1Y + 0.2, cellDepth / 2 + 0.02);
  sec1Mesh.add(sec1ValueText);

  const sec1LabelText = ctx.fontAtlas.createText('Power reserve, NA-01', {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    color: colors.paper
  });
  sec1LabelText.position.set(sec1X - secondaryCellW / 2 + cardPadding, sec1Y - 0.35, cellDepth / 2 + 0.02);
  sec1Mesh.add(sec1LabelText);

  const sec2ValueText = ctx.fontAtlas.createText('214', {
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    color: colors.paper
  });
  sec2ValueText.position.set(sec2X - secondaryCellW / 2 + cardPadding, sec2Y + 0.2, cellDepth / 2 + 0.02);
  sec2Mesh.add(sec2ValueText);

  const sec2LabelText = ctx.fontAtlas.createText('Components per calibre', {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    color: colors.paper
  });
  sec2LabelText.position.set(sec2X - secondaryCellW / 2 + cardPadding, sec2Y - 0.35, cellDepth / 2 + 0.02);
  sec2Mesh.add(sec2LabelText);

  const entranceTimeline = gsap.timeline();
  cells.forEach((cell, index) => {
    gsap.set([cell.material, allTickBars[index].material], { opacity: 0 });
    gsap.set(cell, { y: '-=0.2' });

    entranceTimeline.to([cell.material, allTickBars[index].material], {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, index * 0.08);

    entranceTimeline.to(cell, {
      y: '+=0.2',
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, index * 0.08);
  });
  timelines.push(entranceTimeline);

  group.userData.handlers = {
    pointerenter: function(event) {
      const cell = cells.find(c => c === event.object);
      if (!cell) return;

      const hoverTl = gsap.timeline();
      hoverTl.to(cell.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      });
      timelines.push(hoverTl);
    },
    pointerleave: function(event) {
      const cell = cells.find(c => c === event.object);
      if (!cell) return;

      const releaseTl = gsap.timeline();
      releaseTl.to(cell.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overwrite: 'auto'
      });
      timelines.push(releaseTl);
    }
  };

  group.userData.cleanup = function() {
    timelines.forEach(tl => tl.kill());
    gradientTexture.dispose();
    cellMaterial.dispose();
    cells.forEach(cell => {
      cell.geometry.dispose();
      cell.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    });
  };

  return group;
}
